<?php require_once 'functions.php'; $title='Produk'; $q=trim($_GET['q']??''); $r=$koneksi->prepare('SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id_kategori=p.id_kategori WHERE p.nama_produk LIKE ? ORDER BY p.id_produk DESC'); $like="%$q%"; $r->bind_param('s',$like); $r->execute(); $result=$r->get_result(); include 'header.php'; ?>
<div class="container"><div class="section-head"><div><h1>Daftar Produk</h1><p class="muted">Pilih produk untuk melihat detail dan menambahkannya ke keranjang.</p></div><a class="btn" href="keranjang.php">🛒 Keranjang (<?=cart_count()?>)</a></div><form class="search wide"><input name="q" value="<?=e($q)?>" placeholder="Cari produk..."><button class="btn">Cari</button></form><div class="grid"><?php while($p=$result->fetch_assoc()): ?><article class="card"><div class="thumb"><?= $p['image_url'] ? '<img src="'.e($p['image_url']).'" alt="'.e($p['nama_produk']).'">' : '📦' ?></div><div class="card-body"><small><?=e($p['nama_kategori']??'-')?></small><h3><?=e($p['nama_produk'])?></h3><strong><?=rupiah($p['harga'])?></strong><p class="muted">Stok: <?=$p['stok']?></p><a class="btn full" href="detail_produk.php?id=<?=$p['id_produk']?>">Lihat Detail</a></div></article><?php endwhile;?></div></div><?php include 'footer.php'; ?>
